# Dump the MIL per-op input specs from the coremltools runtime registry to
# opschema.json.
#
# The registry (coremltools/converters/mil/mil/ops/registry.py:63-65) already
# resolves per-opset class selection and string type_domain ids, so the schema
# is read from the imported package rather than parsed out of the .py sources.
#
# Usage:
#   python3 dumpops.py     (writes ../opschema.json)
#
# coremltools is not a build dependency of this repository: the JSON is
# committed and regenerated by hand.

import json
import os
import subprocess
import sys

import coremltools
from coremltools.converters.mil.mil import types
from coremltools.converters.mil.mil.input_type import (
    InternalInputType,
    ListInputType,
    ListOrTensorOrDictInputType,
    PyFunctionInputType,
    StateInputType,
    TensorInputType,
    TupleInputType,
)
from coremltools.converters.mil.mil.ops.helper import _get_version_of_op
from coremltools.converters.mil.mil.ops.registry import SSAOpRegistry

# Tier 1: the ops x/ane/mil emits today.
OPS = [
    "abs",
    "add",
    "cast",
    "concat",
    "const",
    "conv",
    "matmul",
    "maximum",
    "mul",
    "pow",
    "read_state",
    "real_div",
    "reduce_max",
    "reduce_mean",
    "reduce_sum",
    "relu",
    "reshape",
    "scaled_dot_product_attention",
    "sigmoid",
    "slice_by_size",
    "softmax",
    "sqrt",
    "square",
    "sub",
    "tile",
    "transpose",
]

OPSETS = ["iOS15", "iOS16", "iOS17", "iOS18"]

KINDS = [
    (TensorInputType, "tensor"),
    (ListInputType, "list"),
    (ListOrTensorOrDictInputType, "listortensorordict"),
    (TupleInputType, "tuple"),
    (StateInputType, "state"),
    (PyFunctionInputType, "pyfunc"),
    (InternalInputType, "internal"),
]


def kind_of(it):
    # InternalInputType subclasses the typed inputs, so it is tested first.
    if isinstance(it, InternalInputType):
        return "internal"
    for cls, name in KINDS:
        if isinstance(it, cls):
            return name
    raise SystemExit("unknown input type %s" % type(it).__name__)


def domain(tup):
    return [types.builtin_to_string(t) for t in tup]


def op_schema(cls):
    spec = cls.input_spec
    params = []
    for name, it in spec.input_types.items():
        p = {
            "name": name,
            "kind": kind_of(it),
            "const": bool(it.const),
            "optional": bool(it.optional),
        }
        if isinstance(it, TensorInputType):
            if it.type_domain_id is not None:
                p["domain_id"] = it.type_domain_id
            elif it.type_domain:
                p["domain"] = domain(it.type_domain)
        params.append(p)
    domains = {k: domain(v) for k, v in getattr(cls, "type_domains", {}).items()}
    return {"type": cls.__name__, "params": params, "domains": domains}


def main():
    sha = subprocess.run(
        ["git", "-C", coremltools.__path__[0], "rev-parse", "HEAD"],
        capture_output=True, text=True, check=True,
    ).stdout.strip()

    opsets = {}
    for opset in OPSETS:
        target = getattr(coremltools.target, opset)
        ops = {}
        for op_type in OPS:
            variants = SSAOpRegistry.core_ops.get(op_type)
            if not variants:
                raise SystemExit("op %s not registered" % op_type)
            try:
                cls = _get_version_of_op(variants, target)
            except ValueError:
                continue  # op does not exist in this opset
            ops[op_type] = op_schema(cls)
        opsets[opset.lower()] = ops

    out = {
        "coremltools_version": coremltools.__version__,
        "coremltools_commit": sha,
        "opsets": opsets,
    }
    dst = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "opschema.json")
    with open(dst, "w") as f:
        json.dump(out, f, indent=1, sort_keys=True)
        f.write("\n")
    print("wrote %s (coremltools %s from %s)" % (
        os.path.normpath(dst), coremltools.__version__, coremltools.__path__[0]))


if __name__ == "__main__":
    main()
